let state,tab='Members',memberView='grid',search='',sort='name',classFilter='',groupFilter='',unlinkedOnly=false,selectedSession='',familyNames=false,enemyFilter='',streamCategory='',selectedStream='',timer,activeAction,actionPending=false;
