 try{const query=new URLSearchParams({type:$('#war-type').value,month:$('#month').value,capped:$('#capped').value});const r=await fetch(`/api/${guild}/state/?${query}`);if(!r.ok)throw Error('Unable to load guild. Use Refresh to retry.');const loaded=await r.json();if(sequence!==loadSequence)return;state=loaded;$('#error').hidden=true;render();$('#load-status').textContent=tab+' updated';}
