async function parseIkusaText(content,day,offset='+00:00'){
 const output=[];let rollover=0,previous=-1;const lines=content.split('\n');
 for(let i=0;i<lines.length;i++){
  const line=lines[i].trim();if(!line)continue;
  const end=line.indexOf(']');if(!line.startsWith('[')||end<0)throw Error(`Line ${i+1}: missing time`);
  const clock=line.slice(1,end),parts=clock.split(':').map(Number);if(parts.length!==3||parts.some(n=>!Number.isInteger(n)||n<0)||parts[0]>23||parts[1]>59||parts[2]>59)throw Error(`Line ${i+1}: invalid time`);
  const seconds=parts[0]*3600+parts[1]*60+parts[2];if(previous>=0&&seconds<previous){if(previous-seconds>43200)rollover++;else throw Error(`Line ${i+1}: timestamps out of order`);}previous=seconds;
  const body=line.slice(end+1).trim();const kill=body.includes(' has killed ');const separator=kill?' has killed ':' died to ';const split=body.indexOf(separator);if(split<0)throw Error(`Line ${i+1}: unsupported event`);
  const local=body.slice(0,split),remaining=body.slice(split+separator.length),from=remaining.lastIndexOf(' from ');if(from<0)throw Error(`Line ${i+1}: missing guild`);
  const enemy=remaining.slice(0,from);let guild=remaining.slice(from+6),family='';const suffix=guild.lastIndexOf(' (');if(suffix>=0&&guild.endsWith(')')){const names=guild.slice(suffix+2,-1).split(',');family=(names[1]||'').trim();guild=guild.slice(0,suffix);}
  const at=new Date(new Date(day+'T'+clock+offset).getTime()+rollover*86400000).toISOString();const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(day+'|'+i+'|'+line));const id=[...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');
  output.push({id,at,kind:kill?'kill':'death',player:kill?local:enemy,target:kill?enemy:local,guild,family,class:'Unknown'});
 }
 return output;
}
function watchLog(session){
 if(logWatcher){clearInterval(logWatcher);logWatcher=null;toast('Local log reader stopped.');return;}
 if(!window.showOpenFilePicker){toast('This browser does not support live file access. Use the desktop companion or paste an IKUSA log.');return;}
 openAction({label:'Connect local IKUSA log',fields:[{name:'date',label:'Log date',type:'date'},{name:'offset',label:'Recorded timezone offset',type:'text',default:'+00:00'}],custom:async options=>{
  const [handle]=await window.showOpenFilePicker({types:[{description:'IKUSA text log',accept:{'text/plain':['.log','.txt']}}]});let busy=false,lastContent='';
  const read=async()=>{if(busy)return;busy=true;try{const file=await handle.getFile();const text=await file.text();const complete=text.slice(0,text.lastIndexOf('\n')+1);if(complete!==lastContent){const events=await parseIkusaText(complete,options.date,options.offset);for(let i=0;i<events.length;i+=2000)await call('live','ingest',{session:session.id,events:events.slice(i,i+2000)});lastContent=complete;}}catch(e){clearInterval(logWatcher);logWatcher=null;toast('Log reader stopped: '+e.message);return false;}finally{busy=false;}};
  if(await read()===false)throw Error('Could not read the selected log');logWatcher=setInterval(read,500);return {text:'Local log connected. Only parsed events are sent to OpenIQ.'};
 }});
}

function roleConfig(){
 const roles=state.guild.config.roles||{};
 openAction({label:'Discord access roles',fields:['owner','admin','member'].map(tier=>({name:tier,label:tier+' role IDs, one per line',type:'lines',default:(Array.isArray(roles[tier])?roles[tier]:roles[tier]?[roles[tier]]:[]).join('\n')})),custom:p=>call('admin','settings',{config:{roles:p}})});
}
function ticketConfig(){
 const tickets=state.guild.config.tickets||{};
 openAction({label:'Discord ticket channels',fields:[['bot_user_id','Bot user ID'],['staff_role','Ticket staff role ID'],['category_id','Parent category ID (optional)']].map(([name,label])=>({name,label,type:'text',default:tickets[name]||''})),custom:p=>call('admin','settings',{config:{tickets:{...tickets,...p}}})});
}
function welcomeConfig(){
 const welcome=state.guild.config.welcome||{};
 openAction({label:'Welcome cards and roles',fields:[{name:'message',label:'Welcome message',type:'textarea',default:welcome.message||'Welcome to the guild!'},{name:'replace_selection',label:'Replace previous OpenIQ role selection',type:'checkbox',default:welcome.replace_selection||false},{name:'roles',label:'Role label,Discord role ID per line',type:'lines',default:Object.entries(welcome.role_ids||{}).map(([label,id])=>label+','+id).join('\n')}],custom:p=>{
  const pairs=p.roles.map(line=>line.split(',').map(x=>x.trim()));
  if(pairs.some(pair=>pair.length!==2||!pair[0]||!/^\d+$/.test(pair[1]))||pairs.length>25)throw Error('Enter up to 25 role labels with numeric Discord role IDs.');
  return call('admin','settings',{config:{welcome:{...welcome,message:p.message,replace_selection:p.replace_selection,roles:pairs.map(pair=>pair[0]),role_ids:Object.fromEntries(pairs)}}});
 }});
}

const weekdays=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
function scheduleSummary(){
 if(state.role!=='owner')return '<p>Schedule configuration is visible to guild owners.</p>';
 return '<h2>Schedules</h2><div class="grid">'+['weekly','sync'].map(kind=>{
  const config=state.guild.config[kind]||{};
  const title=kind==='weekly'?'Weekly summary':'Roster sync';
  return `<article class="card"><h3>${title}</h3><p>${config.enabled?'Enabled':'Disabled'} &middot; ${esc(weekdays[config.weekday??0]||'Invalid weekday')} at ${esc(String(config.hour??20).padStart(2,'0'))}:00 (${esc(config.timezone||'Pacific/Auckland')})</p><p>Notification channel: ${esc(config.channel||'preview')}</p>${state.role==='owner'?`<button type="button" data-schedule="${kind}">Edit ${title.toLowerCase()} schedule</button>`:''}</article>`;
 }).join('')+'</div>';
}
function scheduleDialog(kind='weekly'){
 const config=state.guild.config[kind]||{};
 openAction({label:kind==='weekly'?'Weekly summary schedule':'Roster sync schedule',fields:[
  {name:'enabled',label:'Enabled',type:'checkbox',default:config.enabled??false},
  {name:'weekday',label:'Weekday',type:'select',options:weekdays,default:weekdays[config.weekday??0]},
  {name:'hour',label:'Hour (0-23)',type:'number',min:0,max:23,step:1,required:true,default:config.hour??20},
  {name:'timezone',label:'Timezone',type:'text',required:true,default:config.timezone||'Pacific/Auckland'},
  {name:'channel',label:'Notification channel',type:'text',required:true,default:config.channel||'preview'}
 ],custom:p=>call('operations','schedule',{...p,kind,weekday:weekdays.indexOf(p.weekday)})});
 const switcher=document.createElement('select');switcher.setAttribute('aria-label','Schedule to edit');
 switcher.innerHTML='<option value="weekly">Weekly summary</option><option value="sync">Roster sync</option>';switcher.value=kind;
 switcher.onchange=()=>{const next=switcher.value;if(confirm('Switch schedules? Unsaved changes in this form will be discarded.'))scheduleDialog(next);else switcher.value=kind;};
 $('#fields').prepend(switcher);
}

function communitySettings(){
 if(state.role!=='owner')return '';
 return ['recruitment_form','ticket_category'].map(kind=>{
  const forms=kind==='recruitment_form';
  const title=forms?'Application forms':'Ticket categories';
  const items=records(kind);
  return `<section class="section"><h2>${title}</h2><button type="button" data-config-kind="${kind}">${forms?'New application form':'New ticket category'}</button><div class="grid">${items.length?items.map(item=>`<article class="card"><h3>${esc(item.title||item.name)}</h3>${forms?`<ol>${(item.questions||[]).map(q=>`<li>${esc(q)}</li>`).join('')}</ol><p>Channel: ${esc(item.channel||'preview')}</p>`:`<p>Staff role: ${esc(item.staff_role||'Default ticket staff role')}</p>`}<button type="button" data-config-kind="${kind}" data-config-id="${esc(item.id)}">Edit ${esc(item.title||item.name)}</button></article>`).join(''):empty(forms?'No application forms yet. Create a form to collect recruitment answers.':'No ticket categories yet. Create a category to organize support requests.')}</div></section>`;
 }).join('');
}
function communityConfig(kind,id){
 const existing=records(kind).find(item=>item.id===id)||{};
 const forms=kind==='recruitment_form';
 openAction({label:(id?'Edit ':'Create ')+(forms?'application form':'ticket category'),fields:forms?[
  {name:'title',label:'Form title',type:'text',required:true,default:existing.title||''},
  {name:'questions',label:'Questions, one per line (1-20)',type:'lines',required:true,default:(existing.questions||[]).join('\n')},
  {name:'channel',label:'Application channel',type:'text',required:true,default:existing.channel||'preview'}
 ]:[
  {name:'name',label:'Category name',type:'text',required:true,default:existing.name||''},
  {name:'staff_role',label:'Staff role ID (optional)',type:'text',default:existing.staff_role||''}
 ],custom:p=>{
  if(forms){if(!p.title.trim())throw Error('Enter a form title');if(p.questions.length<1||p.questions.length>20)throw Error('Supply 1-20 application questions');if(p.questions.some(q=>q.length>500))throw Error('Keep each question within 500 characters');if(!p.channel.trim())throw Error('Enter an application channel or preview');}
  else {if(!p.name.trim())throw Error('Enter a category name');if(p.staff_role&&!/^[0-9]+$/.test(p.staff_role.trim()))throw Error('Staff role ID must contain only digits');p.staff_role=p.staff_role.trim();}
  return call('operations',kind,{...p,...(id?{id}:{})});
 }});
}

const channelLabels={bot:'Bot commands',gear:'Gear commands',welcome:'Welcome messages',events:'Event cards and reminders',leads:'Coaching notifications'};
function channelSummary(){
 if(state.role!=='owner')return '';
 const channels=state.guild.config.channels||{};
 return '<h2>Channels</h2>'+table(['Purpose','Destination'],Object.entries(channelLabels).map(([key,label])=>`<tr><td>${esc(label)}</td><td>${esc(channels[key]||(key==='bot'||key==='gear'?'No channel restriction':'preview'))}</td></tr>`));
}
function channelConfig(){
 const channels=state.guild.config.channels||{};
 openAction({label:'Notification and command channels',fields:Object.entries(channelLabels).map(([name,label])=>({name,label,type:'text',default:channels[name]||''})),custom:p=>{
  const next={...channels};
  for(const [key,value] of Object.entries(p)){
   const channel=value.trim();
   if(channel&&!/^[0-9]+$/.test(channel)&&!(['welcome','events','leads'].includes(key)&&channel==='preview'))throw Error(channelLabels[key]+': enter a numeric channel ID'+(['welcome','events','leads'].includes(key)?' or preview':'')+', or leave blank');
   if(channel)next[key]=channel;else delete next[key];
  }
  return call('admin','settings',{config:{channels:next}});
 }});
 const help=document.createElement('p');help.textContent='Use Discord channel IDs. Blank command channels allow commands in any channel. Blank notification channels use the local preview queue. Saving channels does not enable delivery.';$('#fields').prepend(help);
}

function renderWarChecklist(){
 if(!state.war_checklist)return;
 const section=document.createElement('section');section.className='section';
 section.innerHTML='<h2>War operations checklist</h2><p>Before war: confirm signups and Discord delivery. During war: check captured events. After war: resolve imports and finalize the result. An active capture process alone does not verify combat decoding.</p>'+table(['Event / war','Signups','Capture','Review','Result','Discord'],state.war_checklist.map(w=>`<tr><td>${esc(w.title)}</td><td>${esc(w.signup.status)} ? ${w.signup.confirmed} confirmed ? ${w.signup.waitlisted} waitlisted</td><td>${esc(w.capture.status)} ? ${w.capture.events} events${w.capture.last_seen?' ? '+esc(w.capture.last_seen):''}</td><td>${esc(w.review)} ? ${w.corrections} corrections</td><td>${esc(w.result||'Not finalized')}</td><td>${esc(w.discord)}</td></tr>`));
 $('#panel').prepend(section);
}

