function commandConfig(){
 const current=state.guild.config.command_permissions||{};
 openAction({label:'Command access',fields:[{name:'command',label:'Discord command name',type:'select',options:state.command_names||[],default:Object.keys(current)[0]||(state.command_names||[])[0]},{name:'tier',label:'Minimum role (cannot reduce built-in restrictions)',type:'select',options:['Default','member','admin','owner'],default:'Default'}],custom:p=>{const updated={...current};if(p.tier==='Default')delete updated[p.command];else updated[p.command]=p.tier;return call('admin','settings',{config:{command_permissions:updated}});}});
 const summary=document.createElement('p');summary.textContent=Object.entries(current).map(([command,tier])=>command+': '+tier).join(' | ')||'No extra restrictions configured.';$('#fields').prepend(summary);
}

function integrationSummary(){return '<h2>Setup and integration status</h2><div class="grid">'+(state.integration_status||[]).map(item=>`<article class="card"><h3>${esc(item.name)}</h3><p><strong>${esc(item.status)}</strong></p><p>${esc(item.detail)}</p></article>`).join('')+'</div>';}
